from decimal import Decimal, ROUND_HALF_EVEN


def line_total(lines):
    x = 0
    for line in lines:
        x += line["quantity"] * line["unit_cents"]
    return x


def tax_for(amount_cents, rate):
    tax = Decimal(amount_cents) * Decimal(str(rate))
    return int(tax.quantize(Decimal(1), rounding=ROUND_HALF_EVEN))


def invoice_tax(lines, rate, region):
    # CA-QC: QST must be shown per line (2025 Revenu Quebec audit), so round
    # each line's tax and sum. Everyone else: tax the subtotal once.
    if region == "CA-QC":
        return sum(tax_for(line_total([line]), rate) for line in lines)
    return tax_for(line_total(lines), rate)
EOF
cat >> tests/test_tax.py <<'EOF'


from src.billing.tax import invoice_tax, tax_for


def test_tax_for_rounds_half_even():
    assert tax_for(50, Decimal("0.05")) == 2  # 2.5 -> 2
    assert tax_for(70, Decimal("0.05")) == 4  # 3.5 -> 4


def test_invoice_tax_on_subtotal():
    lines = [{"quantity": 1, "unit_cents": 50}, {"quantity": 1, "unit_cents": 50}]
    assert invoice_tax(lines, Decimal("0.05"), "US-CA") == 5  # 100 * 0.05


def test_invoice_tax_quebec_per_line():
    lines = [{"quantity": 1, "unit_cents": 50}, {"quantity": 1, "unit_cents": 50}]
    assert invoice_tax(lines, Decimal("0.05"), "CA-QC") == 4  # 2 + 2


def test_invoice_tax_exempt_is_zero():
    assert invoice_tax([{"quantity": 3, "unit_cents": 999}], 0, "US-CA") == 0
EOF
